L["visibilityRule_groupedHide_desc"] = "Versteckt das Spielerfenster, sobald du in einer Gruppe oder einem Schlachtzug bist. Während du gruppiert bist, wird nur diese Regel (und Mouseover, falls aktiviert) ausgewertet; andere Sichtbarkeitsregeln werden ignoriert."
