L["visibilityRule_hideInParty"] = "In Gruppe immer ausblenden"
L["visibilityRule_hideInParty_desc"] = "Blendet den Spielerrahmen aus, sobald du in einer Gruppe bist, aber nicht in einem Schlachtzug. Während du in einer Gruppe bist, wird nur diese Regel (und Mouseover, falls aktiviert) ausgewertet; andere Sichtbarkeitsregeln werden ignoriert."
L["visibilityRule_hideInRaid"] = "Im Schlachtzug immer ausblenden"
